import backtrader as bt


class SwingPullbackStrategy(bt.Strategy):
    def __init__(self):
        self.ema12 = bt.indicators.EMA(self.data.close, period=12)
        self.ema26 = bt.indicators.EMA(self.data.close, period=26)
        self.rsi = bt.indicators.RSI(self.data.close, period=14)
        self.atr = bt.indicators.ATR(self.data, period=14)

        self.order = None
        self.stop_order = None
        self.entry_price = None
        self.stop_price = None
        self.breakeven_moved = False
        self.equity_peak = self.broker.getvalue()

        self.long_pullback = False
        self.short_pullback = False
        self.long_trigger_high = None
        self.short_trigger_low = None

    def notify_order(self, order):
        if order.status in (order.Submitted, order.Accepted):
            return

        terminal = (order.Completed, order.Canceled, order.Margin, order.Rejected)

        if order is self.order:
            if order.status == order.Completed:
                if self.position:
                    self.entry_price = order.executed.price
                    self.breakeven_moved = False
                    if self.position.size > 0:
                        self.stop_price = self.entry_price * (1.0 - 0.015)
                        self.stop_order = self.sell(
                            size=abs(self.position.size),
                            exectype=bt.Order.Stop,
                            price=self.stop_price,
                        )
                    else:
                        self.stop_price = self.entry_price * (1.0 + 0.015)
                        self.stop_order = self.buy(
                            size=abs(self.position.size),
                            exectype=bt.Order.Stop,
                            price=self.stop_price,
                        )
                else:
                    self.entry_price = None
                    self.stop_price = None
                    self.breakeven_moved = False
            if order.status in terminal:
                self.order = None

        elif order is self.stop_order and order.status in terminal:
            if order.status == order.Completed:
                self.entry_price = None
                self.stop_price = None
                self.breakeven_moved = False
            self.stop_order = None

    def next(self):
        equity = self.broker.getvalue()
        self.equity_peak = max(self.equity_peak, equity)

        if self.order:
            return

        rsi = self.rsi[0]

        if self.position:
            if self.position.size > 0:
                if not self.breakeven_moved and self.data.high[0] >= self.entry_price * 1.01:
                    if self.stop_order:
                        self.cancel(self.stop_order)
                    self.stop_price = self.entry_price
                    self.stop_order = self.sell(
                        size=abs(self.position.size),
                        exectype=bt.Order.Stop,
                        price=self.stop_price,
                    )
                    self.breakeven_moved = True
                if rsi > 70:
                    if self.stop_order:
                        self.cancel(self.stop_order)
                    self.order = self.close()
            else:
                if not self.breakeven_moved and self.data.low[0] <= self.entry_price * 0.99:
                    if self.stop_order:
                        self.cancel(self.stop_order)
                    self.stop_price = self.entry_price
                    self.stop_order = self.buy(
                        size=abs(self.position.size),
                        exectype=bt.Order.Stop,
                        price=self.stop_price,
                    )
                    self.breakeven_moved = True
                if rsi < 30:
                    if self.stop_order:
                        self.cancel(self.stop_order)
                    self.order = self.close()
            return

        if 30 <= rsi < 40:
            self.long_pullback = True
        if 60 < rsi < 70:
            self.short_pullback = True

        if self.long_pullback and self.rsi[-1] <= 35 < rsi:
            self.long_trigger_high = self.data.high[0]
            self.long_pullback = False
        if self.short_pullback and self.rsi[-1] >= 65 > rsi:
            self.short_trigger_low = self.data.low[0]
            self.short_pullback = False

        if self.equity_peak > 0 and (self.equity_peak - equity) / self.equity_peak > 0.05:
            return

        open_price = self.data.open[0]
        if self.data.high[0] - self.data.low[0] < 0.005 * open_price:
            return

        previous_close = self.data.close[-1]
        true_range = max(
            self.data.high[0] - self.data.low[0],
            abs(self.data.high[0] - previous_close),
            abs(self.data.low[0] - previous_close),
        )
        if true_range > 2 * self.atr[0]:
            return
        if abs(open_price - previous_close) / previous_close > 0.01:
            return

        risk = equity * 0.01
        stop_distance = self.data.close[0] * 0.015
        size = int(risk / stop_distance)
        if size <= 0:
            return

        if (
            self.long_trigger_high is not None
            and self.ema12[0] > self.ema26[0]
            and self.data.close[0] > self.long_trigger_high
        ):
            self.order = self.buy(size=size)
            self.long_trigger_high = None
            self.short_trigger_low = None
        elif (
            self.short_trigger_low is not None
            and self.ema12[0] < self.ema26[0]
            and self.data.close[0] < self.short_trigger_low
        ):
            self.order = self.sell(size=size)
            self.short_trigger_low = None
            self.long_trigger_high = None
